const r={phone:/^1[3-9]\d{9}$/,password:/^(?=.*[a-zA-Z])(?=.*\d)[a-zA-Z\d]{6,20}$/,name:/^[\u4e00-\u9fa5]{2,10}$/},t={phone:[{required:!0,message:"请输入手机号"},{pattern:r.phone,message:"请输入正确的手机号"}],password:[{required:!0,message:"请输入密码"},{min:6,max:20,message:"密码长度6-20位"},{pattern:r.password,message:"密码需包含字母和数字"}],confirmPassword:e=>[{required:!0,message:"请确认密码"},{validator:(a,s)=>!s||e("password")===s?Promise.resolve():Promise.reject(new Error("两次密码输入不一致"))}],name:[{required:!0,message:"请输入姓名"},{pattern:r.name,message:"请输入2-10个中文姓名"}],required:(e="请填写该项")=>[{required:!0,message:e}]};export{t as f};
